    public void simple(CalculadoraService.Processor processor) {
        int porta = Integer.parseInt(jTPorta.getText());
        try {
            //Especificando a forma de transporte    
            TServerTransport serverTransport = new TServerSocket(porta);
            //Instanciando o servidor
            TServer server = new TSimpleServer(new TServer.Args(serverTransport).processor(processor));

            jTALog.append("Iniciando servidor da Calculadora na porta=" + porta + "\n");
            //Iniciando o servidor
            server.serve();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public CalculadoraHandler handler;

    public CalculadoraService.Processor processor;

